import * as T from 'three';
import {createOceanView} from '../plaza/ocean-view.js';
/** Adapter owns only a freshly allocated vista. Accepted ocean code is untouched.
 * Shader-local +Z is east in this view; no astronomy or travel transform changes. */
export function createLookoutOcean({camera,mood='day'}={}){const view=createOceanView({centerX:-6.3,coastZ:18,waterY:-.35,mood}),root=view.root;root.name='island-connections.ocean';const basis=new T.Matrix4().makeRotationY(Math.PI/2),inverse=basis.clone().invert(),water=root.getObjectByName('plaza.ocean.water'),sky=root.getObjectByName('plaza.ocean.sky'),boat=root.getObjectByName('plaza.ocean.boat'),uniforms=water.material.uniforms;boat.visible=false;const direction=new T.Vector3(),horizonPoint=new T.Vector3();let alive=true,currentCamera=camera,currentMood=mood;const nativePrepare=water.onBeforeRender;
 // Broad, near-to-horizon owned rectangle, with native shader depth behind land.
 const a=water.geometry.attributes.position;a.setXYZ(0,-500,-.337,-200);a.setXYZ(1,500,-.337,-200);a.setXYZ(2,500,-.337,500);a.setXYZ(3,-500,-.337,500);a.needsUpdate=true;water.geometry.computeBoundingBox();water.geometry.computeBoundingSphere();
 function prepare(renderer,scene,c=currentCamera){nativePrepare(renderer,scene,c);if(!alive||!c?.isPerspectiveCamera)return;c.updateMatrixWorld(true);uniforms.uViewProjection.value.multiplyMatrices(c.projectionMatrix,c.matrixWorldInverse).multiply(basis);uniforms.uEye.value.copy(c.position).applyMatrix4(inverse);c.getWorldDirection(direction);uniforms.uViewDirection.value.copy(direction).transformDirection(inverse);const horizontal=Math.hypot(direction.x,direction.z),distance=(c.far-direction.y*(-.337-c.position.y))/horizontal;horizonPoint.set(c.position.x+direction.x/horizontal*distance,-.337,c.position.z+direction.z/horizontal*distance).project(c);uniforms.uBoatXZ.value.set(1000000,1000000);const horizon=T.MathUtils.clamp((horizonPoint.y+1)/2,-.3,1.2);uniforms.uHorizon.value=horizon;uniforms.uSunUV.value.set(currentMood==='night'?.30:.69,horizon+Math.max(.1,1-horizon)*(currentMood==='evening'?.22:.56));}
 sky.onBeforeRender=water.onBeforeRender=prepare;prepare(null,null,camera);
 return{root,update(dt,{camera:c,mood:m=currentMood,reduced=false,paused=false}={}){if(!alive)return;if(c?.isPerspectiveCamera)currentCamera=c;currentMood=m;view.update(dt,{mood:m,reduced,paused});prepare(null,null,currentCamera);},snapshot:()=>({...view.snapshot(),activeDrawCalls:2,decorativeBoatVisible:false,perspective:true}),dispose(){if(!alive)return;alive=false;view.dispose();currentCamera=null;}};}
